const svg=paths=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths}</svg>`;
const icons={lista:svg('<rect x="5" y="4" width="14" height="17" rx="3"/><path d="M9 3h6v3H9zM9 11h6M9 16h6"/>'),historico:svg('<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'),precos:svg('<path d="M4 19h16M6 15l5-5 4 3 5-8M16 5h4v4"/>'),despensa:svg('<rect x="4" y="4" width="16" height="16" rx="4"/><path d="M4 12h16M12 4v16M8 8h0M16 16h0"/>'),camera:svg('<path d="M8 6l2-3h4l2 3h3a2 2 0 0 1 2 2v11H3V8a2 2 0 0 1 2-2z"/><circle cx="12" cy="12" r="4"/>')};
document.querySelectorAll('nav button').forEach(b=>{const page=b.dataset.page;b.innerHTML=`<span class="nav-symbol">${icons[page]}</span><span class="nav-label">${{lista:'Lista',historico:'Compras',precos:'Preços',despensa:'Despensa'}[page]}</span>`;b.addEventListener('click',()=>{document.querySelectorAll('nav button').forEach(x=>x.setAttribute('aria-current',x===b?'page':'false'));document.querySelector('.quick-add').hidden=page!=='lista';window.scrollTo({top:0,behavior:'instant'})})});document.querySelector('nav').setAttribute('aria-label','Navegação principal');document.querySelector('[data-page="lista"]').setAttribute('aria-current','page');
const island=document.createElement('div');island.className='mobile-island';island.innerHTML=`<span class="pulse"></span><div class="island-copy"><small id="islandStatus">Sua compra, ao vivo</small><b id="islandTotal"></b></div><button type="button" aria-label="Fotografar etiqueta">${icons.camera}</button>`;document.body.append(island);island.querySelector('button').onclick=()=>scan('label');
function updateIsland(){$('islandTotal').textContent=$('total').textContent;$('islandStatus').textContent=state.items.length?`${state.items.filter(i=>i.checked).length}/${state.items.length} no carrinho`:'Sua compra, ao vivo'}new MutationObserver(updateIsland).observe($('total'),{childList:true,subtree:true,characterData:true});new MutationObserver(updateIsland).observe($('checked'),{childList:true,subtree:true,characterData:true});updateIsland();
const quickAdd=document.createElement('button');quickAdd.className='quick-add';quickAdd.innerHTML='<span aria-hidden="true">+</span> Adicionar produto';quickAdd.onclick=()=>{$('add').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});$('name').focus({preventScroll:true})};document.body.append(quickAdd);
if(window.visualViewport){const initialHeight=window.visualViewport.height;window.visualViewport.addEventListener('resize',()=>{document.body.classList.toggle('keyboard-open',initialHeight-window.visualViewport.height>150&&/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName))});document.addEventListener('focusout',()=>setTimeout(()=>document.body.classList.remove('keyboard-open'),150))}
